"""exp30: Length-stratified analysis — evaluate 9-class DAPT by conversation turn count."""

import json
import numpy as np
from pathlib import Path
from sklearn.metrics import f1_score

PROJ = Path("/root/persuasion_turn_jailbreak_detect")
SEEDS = [42, 123, 456]
BINS = [(1, 3), (4, 6), (7, 10), (11, 999)]
BIN_LABELS = ["1-3", "4-6", "7-10", "10+"]
MODELS = ["9class", "mlm", "vanilla"]

def load_jsonl(path):
    with open(path) as f:
        return [json.loads(line) for line in f]

def get_num_turns(conv):
    if "num_turns" in conv:
        return conv["num_turns"]
    return len(conv.get("turns", []))

def compute_bin_f1(labels, preds, indices):
    if len(indices) == 0:
        return float("nan")
    y_true = [labels[i] for i in indices]
    y_pred = [preds[i] for i in indices]
    unique = set(y_true)
    if len(unique) < 2:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == p)
        acc = tp / len(y_true) if len(y_true) > 0 else 0.0
        return acc  # degenerate: single class, report accuracy instead
    return f1_score(y_true, y_pred, average="macro")

def analyze_dataset(name, pred_path, jb_convs, bn_convs):
    pred_data = json.load(open(pred_path))
    labels = pred_data["labels"]
    n_jb = len(jb_convs)
    n_bn = len(bn_convs)
    assert len(labels) == n_jb + n_bn, f"Label count mismatch: {len(labels)} != {n_jb}+{n_bn}"

    turn_counts = []
    for conv in jb_convs:
        turn_counts.append(get_num_turns(conv))
    for conv in bn_convs:
        turn_counts.append(get_num_turns(conv))

    bin_indices = {}
    for bi, (lo, hi) in enumerate(BINS):
        idxs = [i for i, tc in enumerate(turn_counts) if lo <= tc <= hi]
        bin_indices[BIN_LABELS[bi]] = idxs

    results = {}
    for bl in BIN_LABELS:
        idxs = bin_indices[bl]
        n = len(idxs)
        n_jb_bin = sum(1 for i in idxs if labels[i] == 1)
        n_bn_bin = n - n_jb_bin
        single_class = (n_jb_bin == 0 or n_bn_bin == 0)

        results[bl] = {
            "N": n,
            "n_jb": n_jb_bin,
            "n_bn": n_bn_bin,
            "single_class": single_class,
        }

        for model in MODELS:
            if model not in pred_data["preds"]:
                results[bl][model] = {"mean": float("nan"), "std": float("nan"), "note": "model not found"}
                continue
            f1s = []
            for seed in SEEDS:
                seed_str = str(seed)
                if seed_str not in pred_data["preds"][model]:
                    continue
                preds = pred_data["preds"][model][seed_str]["full"]
                f1 = compute_bin_f1(labels, preds, idxs)
                f1s.append(f1)
            if len(f1s) > 0:
                metric_name = "acc" if single_class else "macro_f1"
                results[bl][model] = {
                    "mean": round(float(np.mean(f1s)), 4),
                    "std": round(float(np.std(f1s)), 4),
                    "per_seed": [round(v, 4) for v in f1s],
                    "metric": metric_name,
                }
            else:
                results[bl][model] = {"mean": float("nan"), "std": float("nan"), "note": "no seeds"}

    turn_count_dist = {bl: {"N": len(bin_indices[bl]),
                            "turn_range": f"{BINS[i][0]}-{BINS[i][1] if BINS[i][1] < 999 else '+'}",
                            "examples": sorted(set(turn_counts[j] for j in bin_indices[bl]))}
                       for i, bl in enumerate(BIN_LABELS)}

    return results, turn_count_dist

def main():
    dd_convs = load_jsonl(PROJ / "data/generated/deceptive_delight_all.jsonl")
    aa_convs = load_jsonl(PROJ / "data/generated/actorattack_all.jsonl")
    test_data = load_jsonl(PROJ / "data/plan_002_splits/test.jsonl")
    test_benign = [c for c in test_data if c["label"] == "benign"]

    print(f"DD: {len(dd_convs)} jb, AA: {len(aa_convs)} jb, Benign: {len(test_benign)} bn")
    print()

    all_results = {}

    for name, jb_convs, pred_path in [
        ("DD_OOD", dd_convs, PROJ / "results/per_sample_predictions/dd_ood_per_sample.json"),
        ("AA_OOD", aa_convs, PROJ / "results/per_sample_predictions/actorattack_per_sample.json"),
    ]:
        results, turn_dist = analyze_dataset(name, pred_path, jb_convs, test_benign)
        all_results[name] = {"per_bin": results, "turn_distribution": turn_dist}

        print(f"=== {name} ===")
        print(f"Turn distribution:")
        for bl in BIN_LABELS:
            td = turn_dist[bl]
            print(f"  {bl}: N={td['N']}, unique_turns={td['examples']}")
        print()
        header = f"{'Bin':<8} {'N':>4} {'Jb':>4} {'Bn':>4}"
        for m in MODELS:
            header += f" | {m:>18}"
        print(header)
        print("-" * len(header))
        for bl in BIN_LABELS:
            r = results[bl]
            row = f"{bl:<8} {r['N']:>4} {r['n_jb']:>4} {r['n_bn']:>4}"
            for m in MODELS:
                if m in r and isinstance(r[m], dict) and "mean" in r[m]:
                    metric = r[m].get("metric", "macro_f1")
                    note = "*" if r["single_class"] else ""
                    row += f" | {r[m]['mean']:.4f}±{r[m]['std']:.4f}{note:>1}"
                else:
                    row += f" | {'N/A':>18}"
            print(row)
        print()
        if any(results[bl]["single_class"] for bl in BIN_LABELS):
            print("  * = single-class bin (metric is accuracy, not macro F1)")
        print()

    out_path = PROJ / "results/exp30_length_stratified.json"
    with open(out_path, "w") as f:
        json.dump(all_results, f, indent=2)
    print(f"Saved to {out_path}")

if __name__ == "__main__":
    main()
